<script setup>
import { computed } from 'vue';
import { money } from '../../../domain/pos';
const props = defineProps({ document: { type: Object, required: true }, compact: Boolean });
const doc = computed(() => props.document);
const currency = computed(() => doc.value.currency || 'RM');
const total = value => money(value || 0, currency.value);
const date = value => value ? String(value).slice(0,10) : '—';
</script>
<template>
  <article class="mf-document" :class="['mf-document--'+doc.format,'mf-document--'+doc.settings.layout,{compact}]" :style="{'--document-accent':doc.settings.primaryColor,fontFamily:doc.settings.fontFamily==='serif'?'Georgia, serif':'Arial, sans-serif',width:doc.format==='receipt'?(doc.settings.paperWidth==='58'?'58mm':'80mm'):'100%',maxWidth:doc.format==='receipt'?'100%':undefined}" aria-label="Document preview">
    <div v-if="doc.pending" class="mf-document-notice">Payment recorded on this device · Awaiting server sync</div>
    <div v-if="doc.invalid" class="mf-document-notice" role="status">{{ doc.previewError }}</div>
    <div v-if="doc.isDraft" class="mf-document-notice">DRAFT · Not issued</div>
    <header class="mf-document-header">
      <div class="mf-document-business">
        <img v-if="doc.settings.showLogo && doc.company.logo" :src="doc.company.logo" class="mf-document-logo" alt="Company logo">
        <h2>{{ doc.company.name }}</h2>
        <p v-if="doc.company.registration">Registration: {{ doc.company.registration }}</p>
        <p v-if="doc.company.address" class="mf-document-pre">{{ doc.company.address }}</p>
        <p v-if="doc.company.phone">{{ doc.company.phone }}</p>
        <p v-if="doc.company.email">{{ doc.company.email }}</p>
      </div>
      <div class="mf-document-identity"><h1>{{ doc.settings.labels.title }}</h1><strong>{{ doc.number || 'Assigned when issued' }}</strong><span v-if="doc.isPaid" class="mf-document-paid">PAID</span><small v-else-if="doc.status && !doc.isDraft">{{ doc.status }}</small></div>
    </header>
    <section class="mf-document-parties">
      <div><h3>{{ doc.settings.labels.billTo }}</h3><strong>{{ doc.customer.name || 'Walk-in customer' }}</strong><p v-if="doc.customer.registration">{{ doc.customer.registration }}</p><p v-if="doc.customer.address" class="mf-document-pre">{{ doc.customer.address }}</p><p v-if="doc.customer.email">{{ doc.customer.email }}</p><p v-if="doc.customer.phone">{{ doc.customer.phone }}</p></div>
      <dl><div><dt>{{ doc.format === 'receipt' ? 'Date & time' : 'Issue date' }}</dt><dd>{{ doc.displayDate || date(doc.date) }}</dd></div><div v-if="doc.dueDate"><dt>Payment due</dt><dd>{{ date(doc.dueDate) }}</dd></div><div v-if="doc.validUntil"><dt>Quote valid until</dt><dd>{{ date(doc.validUntil) }}</dd></div><div v-if="doc.project"><dt>Project</dt><dd>{{ doc.project }}</dd></div><div v-if="doc.cashierName"><dt>Cashier</dt><dd>{{ doc.cashierName }}</dd></div></dl>
    </section>
    <table v-if="doc.format==='receipt'" class="mf-document-items mf-document-receipt-items"><thead><tr><th scope="col">Description</th><th scope="col">Amount</th></tr></thead><tbody><tr v-for="(item,index) in doc.items" :key="index"><td><strong>{{ item.desc }}</strong><small>{{ item.qty }} {{ item.unit }} × {{ total(item.price) }}</small></td><td>{{ total(item.amount) }}</td></tr></tbody></table>
    <table v-else class="mf-document-items"><thead><tr><th scope="col">Description</th><th scope="col">Qty</th><th scope="col">Unit price</th><th scope="col">Amount</th></tr></thead><tbody><tr v-for="(item,index) in doc.items" :key="index"><td><strong>{{ item.desc }}</strong><small v-if="item.unit">{{ item.unit }}</small></td><td>{{ item.qty }}</td><td>{{ total(item.price) }}</td><td>{{ total(item.amount) }}</td></tr><tr v-if="!doc.items.length"><td colspan="4">Add a line item to preview this document.</td></tr></tbody></table>
    <div v-if="!doc.invalid" class="mf-document-totals"><dl><div><dt>Subtotal</dt><dd>{{ total(doc.subtotal) }}</dd></div><div v-if="doc.discountAmount"><dt>Discount ({{ doc.discount }}%)</dt><dd>− {{ total(doc.discountAmount) }}</dd></div><div v-if="doc.tax || doc.taxRate"><dt>Tax ({{ doc.taxRate }}%)</dt><dd>{{ total(doc.tax) }}</dd></div><div class="mf-document-total"><dt>{{ doc.settings.labels.total }}</dt><dd>{{ total(doc.total) }}</dd></div><div v-if="doc.paymentMethod"><dt>Payment</dt><dd>{{ doc.paymentMethod }}</dd></div><div v-if="doc.received != null"><dt>Received</dt><dd>{{ total(doc.received) }}</dd></div><div v-if="doc.change != null"><dt>Change</dt><dd>{{ total(doc.change) }}</dd></div><div v-if="doc.format !== 'receipt' && doc.amountPaid"><dt>Payments recorded</dt><dd>{{ total(doc.amountPaid) }}</dd></div><div v-if="doc.format !== 'receipt' && doc.kind === 'Invoice' && !doc.isDraft && doc.balance != null"><dt>Balance due</dt><dd>{{ total(doc.balance) }}</dd></div></dl></div>
    <section v-if="doc.paymentInstructions || (doc.settings.showPaymentQr && doc.company.qrCode)" class="mf-document-section"><h3>Payment instructions</h3><p v-if="doc.paymentInstructions" class="mf-document-pre">{{ doc.paymentInstructions }}</p><img v-if="doc.settings.showPaymentQr && doc.company.qrCode" :src="doc.company.qrCode" class="mf-document-qr" alt="Payment QR code"></section>
    <section v-if="doc.notes" class="mf-document-section"><h3>Notes</h3><p class="mf-document-pre">{{ doc.notes }}</p></section>
    <section v-if="doc.terms" class="mf-document-section"><h3>{{ doc.kind === 'Quote' ? 'Terms & acceptance' : 'Terms' }}</h3><p class="mf-document-pre">{{ doc.terms }}</p></section>
    <section v-if="doc.settings.showSignature" class="mf-document-signature"><div></div><p>{{ doc.settings.signatureLabel || 'Authorized signature' }}</p></section>
    <footer v-if="doc.footer">{{ doc.footer }}</footer>
  </article>
</template>
<style>
