.mf-document *{box-sizing:border-box}.mf-document p{margin:3px 0}.mf-document h1{font-family:inherit;font-size:clamp(24px,4vw,34px);font-weight:700;letter-spacing:.025em;color:var(--document-accent);margin:0 0 8px}.mf-document h2{font-size:19px;font-weight:700;line-height:1.3;margin:6px 0}.mf-document h3{font-size:10px;letter-spacing:.08em;text-transform:uppercase;font-weight:700;color:var(--document-accent);margin:0 0 8px}
