.mf-document-items{border-collapse:collapse;width:100%;font-size:12px;table-layout:fixed}.mf-document-items th{padding:9px 6px;text-align:right;border-bottom:1px solid var(--document-accent);color:var(--document-accent);font-size:10px;font-weight:700}.mf-document-items td{padding:12px 6px;text-align:right;vertical-align:top;border-bottom:1px solid #e0e6e2;font-variant-numeric:tabular-nums;overflow-wrap:normal}.mf-document-items :is(th,td):first-child{width:48%;text-align:left;overflow-wrap:anywhere;padding-left:0;white-space:pre-line}.mf-document-items :is(th,td):nth-child(2){width:10%}.mf-document-items :is(th,td):last-child{padding-right:0}.mf-document-items td strong{font-weight:500}.mf-document-items td small{display:block;color:#66786f;white-space:normal;margin-top:3px}.mf-document-totals{display:flex;justify-content:flex-end;margin:20px 0}.mf-document-totals dl{min-width:245px;max-width:100%}.mf-document-total{border-top:1px solid #9baea5;font-size:17px;font-weight:700;margin-top:8px;padding-top:9px!important}.mf-document-total dt{color:inherit}.mf-document-section{border-top:1px solid #e0e6e2;padding-top:16px;margin-top:20px}.mf-document-qr{display:block;width:110px;height:110px;object-fit:contain;margin-top:12px}.mf-document-signature{margin-top:45px;max-width:220px}.mf-document-signature>div{border-top:1px solid #a6b5ae}.mf-document-signature p{font-size:10px;color:#66786f;margin-top:7px}.mf-document footer{border-top:1px solid #d1ddd6;padding-top:15px;margin-top:28px;text-align:center;font-size:10px;color:#5e7167;white-space:pre-line}.mf-document-notice{border:1px dashed #b98945;color:#835f2a;padding:9px 12px;margin-bottom:20px;font-size:11px;letter-spacing:.02em}
.mf-document--corporate .mf-document-header{background:#f3f5f2;padding:18px;border:1px solid #d6dfd9}.mf-document--corporate .mf-document-items th,.mf-document--modern .mf-document-items th{background:var(--document-accent);color:white;border:0;padding:10px 8px}.mf-document--corporate .mf-document-items td,.mf-document--modern .mf-document-items td{padding-inline:8px}.mf-document--modern .mf-document-header{border-bottom-width:4px}.mf-document--modern .mf-document-parties{border-left:3px solid var(--document-accent);padding-left:15px}.mf-document--modern .mf-document-totals dl{padding:12px;background:#f3f5f2}
.mf-document--receipt{font-family:Consolas,monospace!important;max-width:360px;padding:14px;font-size:11px}.mf-document--receipt .mf-document-header{display:flex;flex-direction:column;gap:14px;text-align:center;border-bottom:1px dashed #9caea4}.mf-document--receipt .mf-document-identity{text-align:center}.mf-document--receipt h1{font-size:19px}.mf-document--receipt h2{font-size:17px}.mf-document--receipt .mf-document-parties{display:block;margin-bottom:18px}.mf-document--receipt .mf-document-parties>div{margin-bottom:12px}.mf-document--receipt .mf-document-items{font-size:10px}.mf-document--receipt .mf-document-items th{font-size:9px}.mf-document--receipt .mf-document-items :is(td,th):first-child{width:38%}.mf-document--receipt .mf-document-items :is(td,th):nth-child(2){width:12%}.mf-document--receipt .mf-document-totals{display:block}.mf-document--receipt .mf-document-totals dl{min-width:0}.mf-document--receipt .mf-document-total{font-size:14px}.mf-document--receipt .mf-document-qr{margin-inline:auto}.mf-document--receipt .mf-document-notice{font-size:10px}.mf-document.compact{padding:20px;font-size:11px}
