.mf-document--receipt .mf-document-receipt-items :is(th,td):first-child{width:66%}.mf-document--receipt .mf-document-receipt-items :is(th,td):nth-child(2){width:34%;overflow-wrap:anywhere}.mf-document--receipt .mf-document-receipt-items td small{white-space:normal}
@media print{.mf-document{box-shadow:none;max-width:none}.mf-document-items thead{display:table-header-group}.mf-document-items tr,.mf-document-section,.mf-document-signature{break-inside:avoid}}
</style>
